-- The two checklists published on 2026-10-12: a bill you cannot pay
-- (Money) and a deliberate break mid-day (Mindfulness).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-12`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('when-a-bill-you-cannot-pay-arrives', 'When a Bill You Cannot Pay Arrives', 'For the letter or email that asks for money you do not have right now. It helps you find out what is actually owed and by when, make the call before the deadline passes, and keep the fear from turning into weeks of unopened mail.', 'Money', '["Open it and write down the amount and the date — a known number is smaller than an unknown one.", "Check whether it is a final notice or a first one — the two need very different speed.", "Call them before the date, not after — almost every provider has a plan for this.", "Ask directly for a payment plan or an extension — the worst answer is the one you already have.", "List what else is due this month, in order — paying in the wrong order costs the most.", "Look up free debt advice in your state — this is a well-worn problem with real help.", "Tell one person the actual number — money fear thrives on being the only one who knows.", "Put the next unopened letter on today''s list — the pile is what makes this unmanageable."]'::jsonb, 'as needed', array['Money', 'Stress']::text[], 1, '2026-10-12T16:00:00+00:00'::timestamptz),
  ('five-minutes-in-the-middle-of-a-bad-day', 'Five Minutes in the Middle of a Bad Day', 'For a day that has gone wrong by eleven in the morning and still has hours left in it. It helps you take a deliberate break instead of pushing through on fumes, and decide what the rest of the day actually has to contain.', 'Mindfulness', '["Stop mid-task rather than at a finish line — there is no natural break coming.", "Leave the room you have been sitting in — the same four walls keep the same mood going.", "Put the phone in a drawer for the five minutes — a break with scrolling in it is not a break.", "Drink a full glass of water slowly — it is a small ask and it is almost always owed.", "Look at something more than ten feet away — close focus all morning tires more than the work.", "Say what has actually gone wrong in one sentence — a bad day is usually two things, not twelve.", "Cross one thing off the afternoon on purpose — the day got shorter whether you agree or not.", "Go back in on the easiest thing left — restarting needs a low bar, not the hard task."]'::jsonb, 'as needed', array['Mindfulness', 'Self-Care']::text[], 1, '2026-10-12T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
